import React, { useState, useEffect } from 'react';
import axios from 'axios';

const SERVICE_ICONS = {
  barberia: '✂️',
  manicura: '💅',
  pintado: '🎨',
  lizado: '✨',
  tratamiento: '💆',
  otro: '💈'
};

const ClientHome = () => {
  const [services, setServices] = useState([]);
  const [stylists, setStylists] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [selectedStylist, setSelectedStylist] = useState('');
  const [selectedDate, setSelectedDate] = useState('');
  const [selectedTime, setSelectedTime] = useState('');
  const [availableSlots, setAvailableSlots] = useState([]);
  const [clientName, setClientName] = useState('');
  const [clientPhone, setClientPhone] = useState('');
  const [clientEmail, setClientEmail] = useState('');
  const [loading, setLoading] = useState(true);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [servRes, styRes] = await Promise.all([
          axios.get('/api/services'),
          axios.get('/api/auth/stylists')
        ]);
        setServices(servRes.data);
        setStylists(styRes.data);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const handleServiceSelect = (service) => {
    setSelectedService(service);
    setSelectedStylist('');
    setSelectedDate('');
    setSelectedTime('');
    setAvailableSlots([]);
    // Scroll to booking form
    setTimeout(() => {
      document.getElementById('booking-form')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const filteredStylists = selectedService
    ? stylists.filter(s => selectedService.stylists?.some(st => (st._id || st) === s._id))
    : stylists;

  const fetchAvailability = async (stylistId, date) => {
    if (!stylistId || !date) return;
    setLoadingSlots(true);
    try {
      const res = await axios.get(`/api/appointments/availability/${stylistId}?date=${date}`);
      setAvailableSlots(res.data.availableSlots || []);
    } catch (err) {
      console.error(err);
      setAvailableSlots([]);
    } finally {
      setLoadingSlots(false);
    }
  };

  const handleStylistChange = (e) => {
    const val = e.target.value;
    setSelectedStylist(val);
    setSelectedTime('');
    if (val && selectedDate) fetchAvailability(val, selectedDate);
  };

  const handleDateChange = (e) => {
    const val = e.target.value;
    setSelectedDate(val);
    setSelectedTime('');
    if (selectedStylist && val) fetchAvailability(selectedStylist, val);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedService || !selectedStylist || !selectedDate || !selectedTime || !clientName || !clientPhone) {
      setError('Por favor complete todos los campos obligatorios');
      return;
    }
    setSubmitting(true);
    setError('');
    try {
      const res = await axios.post('/api/appointments', {
        clientName,
        clientPhone,
        clientEmail,
        stylistId: selectedStylist,
        serviceId: selectedService._id,
        date: selectedDate,
        startTime: selectedTime
      });
      const stylistName = stylists.find(s => s._id === selectedStylist)?.name || '';
      setSuccess({
        service: selectedService.name,
        stylist: stylistName,
        date: selectedDate,
        time: selectedTime,
        price: res.data.price
      });
      // Reset
      setSelectedService(null);
      setSelectedStylist('');
      setSelectedDate('');
      setSelectedTime('');
      setClientName('');
      setClientPhone('');
      setClientEmail('');
      setAvailableSlots([]);
    } catch (err) {
      setError(err.response?.data?.message || 'Error al reservar la cita');
    } finally {
      setSubmitting(false);
    }
  };

  const getMinDate = () => {
    const today = new Date();
    return today.toISOString().split('T')[0];
  };

  if (loading) {
    return (
      <div className="loading-screen">
        <div className="spinner"></div>
        <p style={{ color: 'var(--text-muted)' }}>Cargando servicios...</p>
      </div>
    );
  }

  return (
    <div>
      {/* Navbar */}
      <nav className="navbar">
        <a href="/" className="navbar-brand">
          <span className="brand-icon">💈</span>
          BarberShop Pro
        </a>
        <div className="navbar-links">
          <a href="#servicios">Servicios</a>
          <a href="#reservar">Reservar</a>
          <a href="/login" className="btn-nav-gold">Acceso Staff</a>
        </div>
      </nav>

      {/* Hero */}
      <section className="hero">
        <div className="hero-content">
          <span className="hero-badge">✦ Barbería Premium ✦</span>
          <h1>Tu Estilo, Nuestra Pasión</h1>
          <p>
            Descubre una experiencia de barbería única. Nuestros estilistas profesionales
            te esperan para transformar tu look con técnicas de vanguardia.
          </p>
          <div className="hero-buttons">
            <a href="#servicios" className="btn btn-gold">Ver Servicios</a>
            <a href="#reservar" className="btn btn-outline">Reservar Cita</a>
          </div>
        </div>
      </section>

      {/* Services */}
      <section className="section" id="servicios">
        <div className="section-title">
          <h2>Nuestros Servicios</h2>
          <div className="gold-line"></div>
          <p>Selecciona el servicio que deseas para comenzar tu reserva</p>
        </div>
        <div className="services-grid">
          {services.filter(s => s.isActive !== false).map(service => (
            <div
              key={service._id}
              className={`service-card ${selectedService?._id === service._id ? 'selected' : ''}`}
              onClick={() => handleServiceSelect(service)}
            >
              <div className="service-icon">
                {SERVICE_ICONS[service.category] || '💈'}
              </div>
              <h3>{service.name}</h3>
              <p>{service.description}</p>
              <div className="service-meta">
                <span className="service-price">S/ {service.price}</span>
                <span className="service-duration">🕐 {service.duration} min</span>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Booking Form */}
      {selectedService && (
        <section className="section" id="reservar">
          <div className="booking-section" id="booking-form">
            <h2>Reservar: {selectedService.name}</h2>
            <p className="subtitle">
              {selectedService.description} — S/ {selectedService.price} — {selectedService.duration} min
            </p>

            {error && <div className="error-msg">{error}</div>}

            <form onSubmit={handleSubmit}>
              <div className="form-grid">
                <div className="form-group">
                  <label>Nombre Completo *</label>
                  <input
                    type="text"
                    value={clientName}
                    onChange={(e) => setClientName(e.target.value)}
                    placeholder="Tu nombre"
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Teléfono *</label>
                  <input
                    type="tel"
                    value={clientPhone}
                    onChange={(e) => setClientPhone(e.target.value)}
                    placeholder="999 999 999"
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Email (opcional)</label>
                  <input
                    type="email"
                    value={clientEmail}
                    onChange={(e) => setClientEmail(e.target.value)}
                    placeholder="tu@email.com"
                  />
                </div>
                <div className="form-group">
                  <label>Estilista *</label>
                  <select value={selectedStylist} onChange={handleStylistChange} required>
                    <option value="">Seleccionar estilista</option>
                    {filteredStylists.map(s => (
                      <option key={s._id} value={s._id}>{s.name}</option>
                    ))}
                  </select>
                </div>
                <div className="form-group">
                  <label>Fecha *</label>
                  <input
                    type="date"
                    value={selectedDate}
                    onChange={handleDateChange}
                    min={getMinDate()}
                    required
                  />
                </div>
              </div>

              {selectedStylist && selectedDate && (
                <div className="form-group" style={{ marginBottom: '24px' }}>
                  <label>Horario Disponible *</label>
                  {loadingSlots ? (
                    <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem' }}>Cargando horarios...</p>
                  ) : availableSlots.length > 0 ? (
                    <div className="time-slots">
                      {availableSlots.map(slot => (
                        <button
                          type="button"
                          key={slot}
                          className={`time-slot ${selectedTime === slot ? 'selected' : ''}`}
                          onClick={() => setSelectedTime(slot)}
                        >
                          {slot}
                        </button>
                      ))}
                    </div>
                  ) : (
                    <p style={{ color: 'var(--danger)', fontSize: '0.9rem' }}>
                      No hay horarios disponibles para esta fecha
                    </p>
                  )}
                </div>
              )}

              <button
                type="submit"
                className="btn btn-gold"
                disabled={submitting || !selectedTime}
                style={{ width: '100%', justifyContent: 'center' }}
              >
                {submitting ? 'Reservando...' : '💈 Confirmar Reserva'}
              </button>
            </form>
          </div>
        </section>
      )}

      {/* Footer */}
      <footer style={{
        textAlign: 'center',
        padding: '3rem 2rem',
        borderTop: '1px solid var(--border)',
        color: 'var(--text-muted)',
        fontSize: '0.85rem'
      }}>
        <p style={{ marginBottom: '8px' }}>
          <span style={{ color: 'var(--gold)', fontSize: '1.2rem' }}>💈</span>{' '}
          <strong style={{ color: 'var(--text-primary)' }}>BarberShop Pro</strong>
        </p>
        <p>© 2026 Todos los derechos reservados</p>
      </footer>

      {/* Success Modal */}
      {success && (
        <div className="success-overlay" onClick={() => setSuccess(null)}>
          <div className="success-card" onClick={(e) => e.stopPropagation()}>
            <span className="check-icon">✅</span>
            <h2>¡Cita Reservada!</h2>
            <p><strong>Servicio:</strong> {success.service}</p>
            <p><strong>Estilista:</strong> {success.stylist}</p>
            <p><strong>Fecha:</strong> {success.date}</p>
            <p><strong>Hora:</strong> {success.time}</p>
            <p><strong>Precio:</strong> S/ {success.price}</p>
            <div style={{ marginTop: '24px' }}>
              <button className="btn btn-gold" onClick={() => setSuccess(null)}>
                Entendido
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClientHome;
